"use strict";(globalThis.webpackChunkwebsite||=[]).push([[907],{3984(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Getting started","collapsed":false,"items":[{"type":"link","href":"/libmisb-release/manual/docs/intro","label":"Choose your SDK","docId":"intro","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/installation","label":"Install the SDK","docId":"installation","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/getting-started","label":"Decode your first native packet","docId":"getting-started","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/wasm-decoders","label":"Decode your first web packet","docId":"wasm-decoders","unlisted":false}],"collapsible":true},{"type":"category","label":"Basic scenarios","items":[{"type":"link","href":"/libmisb-release/manual/docs/read-fields","label":"Read the timestamp and version","docId":"read-fields","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/roundtrip","label":"Encode and validate (native only)","docId":"roundtrip","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Advanced usage","items":[{"type":"link","href":"/libmisb-release/manual/docs/streaming","label":"Decode fragmented packets and PES payloads","docId":"streaming","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/revisions-and-json","label":"Revisions, exact JSON, and partial results","docId":"revisions-and-json","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/nested","label":"Inspect nested metadata","docId":"nested","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/license","label":"License modes and activation","docId":"license","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/deployment","label":"Load and redistribute the SDK","docId":"deployment","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Reference and troubleshooting","items":[{"type":"link","href":"/libmisb-release/manual/docs/capabilities","label":"Supported operations","docId":"capabilities","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/api","label":"SDK API reference","docId":"api","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/abi-interface","label":"Native ABI ownership and status","docId":"abi-interface/index","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/abi-interface/misb0601","label":"ST 0601 C ABI","docId":"abi-interface/misb0601","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/abi-interface/klv","label":"Raw KLV C ABI","docId":"abi-interface/klv","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/web-api","label":"Web decoder API","docId":"web-api","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/integrations/decoded-json","label":"Convert already-decoded JSON","docId":"integrations/decoded-json","unlisted":false},{"type":"link","href":"/libmisb-release/manual/docs/troubleshooting","label":"Troubleshooting","docId":"troubleshooting","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"abi-interface/index":{"id":"abi-interface/index","title":"Native ABI ownership and status","description":"Supply caller-owned inputs for the duration of each call. Initialize output structures before use. Copy any data you need before releasing its owning result. Use the matching free function from the same library; buffers inside a compound result belong to that result.","sidebar":"tutorialSidebar"},"abi-interface/klv":{"id":"abi-interface/klv","title":"Raw KLV C ABI","description":"Load the platform\'s libmisb shared library and initialize it with LibmisbLicenseInitialize. Raw reads require the decode capability and writes require encode. Keys and item values are returned as bytes.","sidebar":"tutorialSidebar"},"abi-interface/misb0601":{"id":"abi-interface/misb0601","title":"ST 0601 C ABI","description":"Use include/misb0601.h for the signatures, enum values and structure layouts shipped with your binary. Call Misb0601LicenseInitialize and inspect the three capability flags.","sidebar":"tutorialSidebar"},"api":{"id":"api","title":"SDK API reference","description":"| Binding | Application entrypoint |","sidebar":"tutorialSidebar"},"capabilities":{"id":"capabilities","title":"Supported operations","description":"| Operation | Native SDK | Browser and Node.js decoder |","sidebar":"tutorialSidebar"},"deployment":{"id":"deployment","title":"Load and redistribute the SDK","description":"Ship the platform libraries, the binding your application uses, and the third-party notices supplied in the archive. Load the library from your application\'s installed location. Pass its absolute path when loading dynamically. Match the process architecture, including the architecture of your Python or .NET runtime.","sidebar":"tutorialSidebar"},"getting-started":{"id":"getting-started","title":"Decode your first native packet","description":"Open your installed SDK directory or extract the portable native ZIP. Run the archive-root commands below from that directory. Keep lib/, examples/, and example.klv together. Start with no token set. For a web application, follow the browser and Node.js quickstart.","sidebar":"tutorialSidebar"},"installation":{"id":"installation","title":"Install the SDK","description":"Choose the installer for your operating system and processor. Installation works offline in your own account. Each SDK version has its own directory. The native libraries, headers, language bindings, examples, notices and example.klv are installed together. Leave the web component selected to include the browser decoder, Node example and npm tarball under web/.","sidebar":"tutorialSidebar"},"integrations/decoded-json":{"id":"integrations/decoded-json","title":"Convert already-decoded JSON","description":"Use @impleotv/libmisb-web when your input is a tag-keyed ST 0601 object. Install the JSON helper with npm install @impleotv/libmisb-web. It maps known tag keys, including supported nested sets, to more descriptive keys.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Choose your SDK","description":"Start with the supplied packet, example.klv. Its timestamp is 9007199254740993 and its ST 0601 revision is 19. Both examples run in demo mode.","sidebar":"tutorialSidebar"},"license":{"id":"license","title":"License modes and activation","description":"The supplied packet works without credentials. With an absent or invalid token, ST 0601 demo mode retains tags 1 through 14 and tag 65. This includes the timestamp, mission ID, version, and checksum. Use a licensed decoder to access nested metadata and raw KLV.","sidebar":"tutorialSidebar"},"nested":{"id":"nested","title":"Inspect nested metadata","description":"With a licensed decoder, read ST 0601 tag 48 as the security local set (ST 0102) and tag 74 as VMTI (ST 0903). First check that the parent field is present. Demo packets omit both fields; a licensed packet can omit either one too.","sidebar":"tutorialSidebar"},"read-fields":{"id":"read-fields","title":"Read the timestamp and version","description":"In the native quickstart, the decoder returns tag-keyed JSON. Read tag 2 as an unsigned 64-bit integer and tag 65 as the packet version. The supplied packet has values 9007199254740993 and 19. Fields are sparse: check for presence before using a value.","sidebar":"tutorialSidebar"},"revisions-and-json":{"id":"revisions-and-json","title":"Revisions, exact JSON, and partial results","description":"Most applications should let the decoder detect the revision from tag 65. Inspect that value before interpreting fields whose definitions vary by revision. When an upstream format omits the version, set the decoder\'s missing-version option and specify the revision you expect. Use an explicit revision override only when you know which schema applies.","sidebar":"tutorialSidebar"},"roundtrip":{"id":"roundtrip","title":"Encode a packet and inspect a validation finding","description":"Native SDK. Start with the built example from Getting started. Append --roundtrip to its run command. For example, from examples/go on Linux run go run . ../../lib/misb0601.so ../../example.klv --roundtrip.","sidebar":"tutorialSidebar"},"streaming":{"id":"streaming","title":"Decode fragmented packets and PES payloads","description":"Pass the payload bytes from your demultiplexer. A chunk can contain part of a KLV packet or several packets. Supply PTS when it is known for a demuxed PES payload. The ST 0601 timestamp inside the decoded metadata is a separate value.","sidebar":"tutorialSidebar"},"troubleshooting":{"id":"troubleshooting","title":"Troubleshooting","description":"| Symptom | Check |","sidebar":"tutorialSidebar"},"wasm-decoders":{"id":"wasm-decoders","title":"Decode your first web packet","description":"Open web/ in your installed SDK directory, or extract the static web ZIP. Both contain a ready-to-run module, the Rust decoder binary, TypeScript declarations, and the same example.klv as the native SDK. Start with no token set.","sidebar":"tutorialSidebar"},"web-api":{"id":"web-api","title":"Web decoder API","description":"Create one decoder per independent session. Pass licenseToken for web activation and wasm for a custom URL, module, or buffer. The supplied index.d.mts lists supported options.","sidebar":"tutorialSidebar"}}}}')}}]);